public static void main(Args _args)
{

    if(_args.record())
    {
        DirPartyContactInfoView  dirPartyContactInfoView;

        CustTable       custTable = _args.record();
        DirPartyTable   dirpartyTable = DirPartyTable::findRec(custTable.Party);

        select firstonly DirPartyContactInfoView
            where DirPartyContactInfoView.Party == custTable.Party
            && DirPartyContactInfoView.Type == LogisticselectronicaddressMethodType::Email
            && DirPartyContactInfoView.IsPrimary == NoYes::Yes;

        if(DirPartyContactInfoView)
        {
            SysMailerMessageBuilder messageBuilder = new SysMailerMessageBuilder();

            RetailParameters retailParameters = RetailParameters::find();

            if(retailParameters.ARGSysEmailId)
            {
                SysEmailTable sysEmailTable = SysEmailTable::find(retailParameters.ARGSysEmailId);

                if(sysEmailTable)
                {
                    try
                    {
                        SysEmailMessageTable sysEmailMessageTable = SysEmailMessageTable::find(sysEmailTable.emailId, sysEmailTable.DefaultLanguage);

                        messageBuilder.setFrom(sysEmailTable.SenderAddr);
                        messageBuilder.addTo(DirPartyContactInfoView.Locator);
                        messageBuilder.setSubject(sysEmailMessageTable.Subject);
                        messageBuilder.setBody(sysEmailMessageTable.Mail, true);

                        SysMailerFactory::sendNonInteractive(messageBuilder.getMessage());

                        Info("@ARGResetPassword:RstPwd007");
                    }
                    catch(Exception::CLRError)
                    {
                        System.Exception ex = CLRInterop::getLastException();
                        Error(ex.Message);
                    }                        
                }
                else
                {
                    throw Error("@ARGResetPassword:RstPwd001");
                }
            }
            else
            {
                throw Error("@ARGResetPassword:RstPwd002");
            }
        }
        else
        {
            throw Error("@ARGResetPassword:RstPwd006");
        }
    }
    else
    {
        throw Error("@ARGResetPassword:RstPwd005");
    }

}
